#!/usr/bin/env python3
"""Validate meeting follow-up outputs against tagged notes and a prior tracker."""

from __future__ import annotations

import argparse
import csv
import json
import re
import sys
from collections import Counter
from datetime import date
from pathlib import Path


HEADER = ["action_id", "owner", "due_date", "status", "action", "source"]
QA_KEYS = [
    "schema_version",
    "meeting_date",
    "decision_count",
    "action_count",
    "open_question_count",
    "deferred_idea_count",
    "tracker_rows_added",
    "missing_due_dates",
    "checks",
]
CHECKS = ["source-citations", "tracker-schema", "no-idea-promotion"]
HEADINGS = [
    "# Meeting follow-up",
    "## Decisions",
    "## Action items",
    "## Open questions",
    "## Deferred ideas",
]
SECTION_TAG = {
    "## Decisions": "DECISION",
    "## Action items": "ACTION",
    "## Open questions": "QUESTION",
    "## Deferred ideas": "IDEA",
}
OWNERS = {
    "Maya Chen": "@maya",
    "Leo Park": "@leo",
    "Nina Gomez": "@nina",
    "Oliver Smith": "@oliver",
}
NOTE_RE = re.compile(
    r"^\s*([A-Za-z0-9_-]+)\s+\[(DECISION|ACTION|IDEA|QUESTION|CHATTER)\]\s+(.+?)\s*$"
)
DATE_RE = re.compile(r"\b(\d{4}-\d{2}-\d{2})\b")
MEETING_DATE_RE = re.compile(r"(?im)^\s*Meeting date:\s*(\d{4}-\d{2}-\d{2})\s*$")
ID_RE = re.compile(r"^M-\d{6}-\d{2}$")


def read_text(path: Path) -> str:
    return path.read_text(encoding="utf-8")


def parse_notes(path: Path) -> tuple[str, list[dict[str, str]]]:
    text = read_text(path)
    match = MEETING_DATE_RE.search(text)
    if not match:
        raise ValueError("notes must contain 'Meeting date: YYYY-MM-DD'")
    meeting_date = match.group(1)
    date.fromisoformat(meeting_date)
    entries = []
    for line in text.splitlines():
        note = NOTE_RE.match(line)
        if note:
            entries.append({"source": note.group(1), "tag": note.group(2), "text": note.group(3)})
    sources = [entry["source"] for entry in entries]
    if len(sources) != len(set(sources)):
        raise ValueError("note source markers must be unique")
    return meeting_date, entries


def read_csv(path: Path) -> tuple[list[str], list[list[str]]]:
    with path.open(newline="", encoding="utf-8-sig") as handle:
        rows = list(csv.reader(handle))
    if not rows:
        raise ValueError(f"{path} is empty")
    return rows[0], rows[1:]


def validate_followup(path: Path, entries: list[dict[str, str]], errors: list[str]) -> None:
    text = read_text(path)
    heading_lines = [line for line in text.splitlines() if line.startswith("#")]
    if heading_lines != HEADINGS:
        errors.append("follow-up.md headings are not exact or in the required order")
        return
    expected = {tag: [entry["source"] for entry in entries if entry["tag"] == tag] for tag in SECTION_TAG.values()}
    found = {tag: [] for tag in SECTION_TAG.values()}
    action_bullets: list[str] = []
    current = None
    for line in text.splitlines():
        if line in SECTION_TAG:
            current = SECTION_TAG[line]
        elif line.startswith("-") and current:
            marker = re.search(r"\[([A-Za-z0-9_-]+)\]\s*$", line)
            if not marker:
                errors.append(f"follow-up bullet lacks a final source marker: {line}")
            else:
                found[current].append(marker.group(1))
                if current == "ACTION":
                    action_bullets.append(line)
    for tag, sources in expected.items():
        if found[tag] != sources:
            errors.append(f"follow-up {tag} sources {found[tag]} do not match notes {sources}")
    actions = [entry for entry in entries if entry["tag"] == "ACTION"]
    action_re = re.compile(
        r"^- (@maya|@leo|@nina|@oliver|TBD) \| due (\d{4}-\d{2}-\d{2}|TBD) \| .+ \[([A-Za-z0-9_-]+)\]$"
    )
    for index, (bullet, action) in enumerate(zip(action_bullets, actions), 1):
        match = action_re.fullmatch(bullet)
        if not match:
            errors.append(f"follow-up action {index} does not match the required bullet format")
            continue
        owner, due, source = match.groups()
        if owner != (explicit_owner(action["text"]) or "TBD"):
            errors.append(f"follow-up action {index} has an incorrect owner")
        if due != (explicit_due(action["text"]) or "TBD"):
            errors.append(f"follow-up action {index} has an incorrect due date")
        if source != action["source"]:
            errors.append(f"follow-up action {index} has an incorrect source")


def explicit_owner(text: str) -> str | None:
    first_field = text.split("|", 1)[0].strip()
    if first_field in OWNERS:
        return OWNERS[first_field]
    matches = [handle for name, handle in OWNERS.items() if name in text]
    return matches[0] if len(matches) == 1 else None


def explicit_due(text: str) -> str | None:
    fields = [field.strip() for field in text.split("|")]
    if len(fields) >= 3 and re.fullmatch(r"\d{4}-\d{2}-\d{2}", fields[1]):
        try:
            date.fromisoformat(fields[1])
            return fields[1]
        except ValueError:
            pass
    for value in DATE_RE.findall(text):
        try:
            date.fromisoformat(value)
            return value
        except ValueError:
            continue
    return None


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Validate follow-up.md, actions.csv, and qa.json without modifying them.",
        epilog="Exit codes: 0 valid, 1 validation failures, 2 input or usage error.",
    )
    parser.add_argument("--notes", required=True, type=Path, help="tagged meeting notes")
    parser.add_argument("--tracker", required=True, type=Path, help="existing tracker before this meeting")
    parser.add_argument("--output-dir", required=True, type=Path, help="directory containing the three outputs")
    args = parser.parse_args()

    try:
        meeting_date, entries = parse_notes(args.notes)
        old_header, old_rows = read_csv(args.tracker)
        new_header, new_rows = read_csv(args.output_dir / "actions.csv")
        qa = json.loads(read_text(args.output_dir / "qa.json"))
        if not isinstance(qa, dict):
            raise ValueError("qa.json must contain one JSON object")
        followup_path = args.output_dir / "follow-up.md"
        if not followup_path.is_file():
            raise ValueError("missing follow-up.md")
    except (OSError, UnicodeError, csv.Error, json.JSONDecodeError, ValueError) as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 2

    errors: list[str] = []
    if old_header != HEADER:
        errors.append(f"existing tracker header must be {','.join(HEADER)}")
    if new_header != HEADER:
        errors.append(f"output tracker header must be {','.join(HEADER)}")
    if new_rows[: len(old_rows)] != old_rows:
        errors.append("existing tracker rows were not preserved unchanged")

    actions = [entry for entry in entries if entry["tag"] == "ACTION"]
    added = new_rows[len(old_rows) :] if new_rows[: len(old_rows)] == old_rows else []
    if len(added) != len(actions):
        errors.append(f"tracker added {len(added)} rows; expected {len(actions)}")

    prefix = date.fromisoformat(meeting_date).strftime("M-%y%m%d-")
    expected_ids = [f"{prefix}{index:02d}" for index in range(1, len(actions) + 1)]
    all_ids = [row[0] for row in new_rows if len(row) == len(HEADER)]
    if len(all_ids) != len(set(all_ids)):
        errors.append("tracker action_id values are not unique")
    if any(len(row) != len(HEADER) for row in new_rows):
        errors.append("tracker contains a row with the wrong number of columns")

    for index, (row, action) in enumerate(zip(added, actions)):
        if len(row) != len(HEADER):
            continue
        expected_id = expected_ids[index]
        if row[0] != expected_id or not ID_RE.fullmatch(row[0]):
            errors.append(f"action {index + 1} identifier must be {expected_id}")
        if row[3] != "open":
            errors.append(f"{expected_id} status must be open")
        if row[5] != action["source"]:
            errors.append(f"{expected_id} source must be {action['source']}")
        owner = explicit_owner(action["text"])
        if row[1] != (owner or "TBD"):
            errors.append(f"{expected_id} owner must be {owner or 'TBD'}")
        due = explicit_due(action["text"])
        if row[2] != (due or "TBD"):
            errors.append(f"{expected_id} due_date must be {due or 'TBD'}")

    idea_sources = {entry["source"] for entry in entries if entry["tag"] == "IDEA"}
    if any(len(row) == len(HEADER) and row[5] in idea_sources for row in added):
        errors.append("an idea was promoted to a tracker row")

    counts = Counter(entry["tag"] for entry in entries)
    missing_due = [row[0] for row in added if len(row) == len(HEADER) and row[2] == "TBD"]
    expected_qa = {
        "schema_version": 1,
        "meeting_date": meeting_date,
        "decision_count": counts["DECISION"],
        "action_count": counts["ACTION"],
        "open_question_count": counts["QUESTION"],
        "deferred_idea_count": counts["IDEA"],
        "tracker_rows_added": len(actions),
        "missing_due_dates": missing_due,
        "checks": CHECKS,
    }
    if list(qa.keys()) != QA_KEYS:
        errors.append("qa.json keys are not exact or in the required order")
    for key, value in expected_qa.items():
        if qa.get(key) != value:
            errors.append(f"qa.json {key} is {qa.get(key)!r}; expected {value!r}")

    validate_followup(followup_path, entries, errors)
    if errors:
        for error in errors:
            print(f"ERROR: {error}", file=sys.stderr)
        return 1
    print(f"OK: validated {len(actions)} actions for meeting {meeting_date}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
